<?php
if(!defined("FPDUAL_ENTRY")) {http_response_code(404);exit;}
function tutor_groups(array $d,string $cid):array { $a=$d['accounts'][$_SESSION['account']??'']??[];return array_intersect_key($d['courses'][$cid]['groups']??[],array_fill_keys($a['grants'][$cid]??[],true)); }
function tutor_scope(array $d,string $cid,string $gid):void {if(($_SESSION['role']??'')!=='tutor'||!isset(tutor_groups($d,$cid)[$gid]))fail('Grupo no autorizado',403);}
function tutor_company_scope(array $d,string $cid,string $eid):void { $l=participation($d,$cid,$eid);tutor_scope($d,$cid,$l['group']); }
function panel_url(string $v,string $cid='',string $p='',string $g=''):string{return 'index.php?'.http_build_query(array_filter(['v'=>$v,'c'=>$cid,'p'=>$p,'g'=>$g],fn($x)=>$x!==''));}
function panel_nav(string $role,string $view,string $cid):void {
 $p=(string)($_GET['p']??'home');$g=(string)($_GET['g']??'');global $d;if($role==='tutor'&&!tutor_groups($d,$cid)){foreach($d['courses'] as $id=>$cc)if(tutor_groups($d,$id)){$cid=$id;$g='';}}if($role==='company'&&!company_links($d,$cid,$_SESSION['company'])){foreach($d['courses'] as $id=>$cc)if(company_links($d,$id,$_SESSION['company']))$cid=$id;}
 $items=match($role){'admin'=>['GESTIÓN'=>['dashboard'=>['◈','Cuadro de mando'],'directory'=>['▤','Empresas'],'interests'=>['✓','Solicitudes de interés'],'first_contacts'=>['☎','Primer contacto'],'mail_preparer'=>['✉','Preparar correo'],'agenda'=>['◷','Agenda'],'campaigns'=>['✉','Campañas'],'inbox'=>['▣','Buzón empresarial'],'students'=>['▣','Alumnado'],'documents'=>['▧','Expedientes']], 'ADMINISTRACIÓN'=>['courses'=>['▦','Cursos y grupos'],'teachers'=>['♙','Tutores docentes'],'registrations'=>['✓','Registros'],'settings'=>['⚙','Configuración']]],'company'=>['MI EMPRESA'=>['home'=>['◈','Inicio'],'profile'=>['▤','Datos de empresa'],'sites'=>['⌖','Centros de trabajo'],'tutors'=>['♙','Tutores de empresa']], 'FORMACIÓN'=>['offers'=>['▦','Mis colaboraciones'],'docs'=>['▧','Documentación'],'account'=>['⚙','Mi cuenta']]],'tutor'=>['MI GRUPO'=>['home'=>['◈','Cuadro de mando'],'companies'=>['▤','Empresas y plazas'],'students'=>['▣','Alumnado'],'agenda'=>['◷','Seguimiento'],'docs'=>['▧','Documentación'],'account'=>['⚙','Mi cuenta']]],default=>[]};
 echo '<aside class="sidebar"><a class="sidebrand" href="'.h(panel_url(match($role){'admin'=>'dashboard','company'=>'portal',default=>'teacher'},$cid)).'"><span class="mark">FP</span><span>Dual Conecta<b>A&amp;G</b><small>Administración y Gestión</small></span></a><div class="side-role">'.h(match($role){'admin'=>'Administración del centro','company'=>'Portal de empresas',default=>'Tutor docente'}).'</div><nav aria-label="Menú principal">';foreach($items as $section=>$entries){echo '<div class="navlabel">'.h($section).'</div>';foreach($entries as $key=>[$ic,$label]){$selected=$role==='admin'?($view===$key||($key==='directory'&&in_array($view,['company','import']))):$p===$key;$url=$role==='admin'?panel_url($key,$cid):panel_url($role==='company'?'portal':'teacher',$cid,$key,$g);echo '<a '.($selected?'class="selected" aria-current="page" ':'').'href="'.h($url).'"><span class="navicon">'.h($ic).'</span>'.h($label).'</a>';}}echo '</nav><div class="sidebottom"><a href="index.php?v=landing">↗ Landing pública</a>';echo '</div></aside>';
}
function panel_metric(string $label,$v,string $note=''):void{echo '<div class="metric card"><small>'.h($label).'</small><strong>'.h($v).'</strong><span class="muted">'.h($note).'</span></div>';}
function panel_course_switch(array $opts,string $cid,string $view,string $p=''):void{echo '<form class="switcher" method="get"><input type="hidden" name="v" value="'.h($view).'"><input type="hidden" name="p" value="'.h($p).'"><label>Curso académico<select name="c">';foreach($opts as $k=>$label)echo '<option value="'.h($k).'"'.($k===$cid?' selected':'').'>'.h($label).'</option>';echo '</select></label><button class="secondary">Cambiar</button></form>';}
function teacher_admin(array $d,string $cid,array $gs,bool $ed):void{
 echo '<section class="card"><h2>Equipo docente · '.h($d['courses'][$cid]['name']).'</h2><p class="muted">Cada docente solo puede consultar y gestionar sus grupos asignados. Los permisos se establecen por curso académico.</p>';
 $selected=(string)($_GET['record']??'');$base='?v=teachers&c='.rawurlencode($cid);if($selected!=='')echo '<a class="button secondary" href="'.h($base).'">← Volver al equipo docente</a>';foreach($d['accounts'] as $aid=>$acc){if(($acc['role']??'company')!=='tutor')continue;if($selected===''){echo '<div class="record-toolbar"><strong>'.h($acc['name'].' · '.$acc['email']).'</strong><a class="button secondary" href="'.h($base.'&record='.rawurlencode((string)$aid)).'">Abrir ficha</a></div>';continue;}if((string)$aid!==$selected)continue;echo '<div class="record-card"><h2>'.h($acc['name'].' · '.$acc['email']).'</h2>';if($ed){form_start('teacher_grant',['c'=>$cid,'aid'=>$aid]);foreach($gs as $gid=>$n)echo '<label class="check"><input type="checkbox" name="groups[]" value="'.h($gid).'"'.(in_array($gid,$acc['grants'][$cid]??[],true)?' checked':'').'>'.h($n).'</label>';end_form('Guardar permisos del curso');}else foreach($acc['grants'][$cid]??[] as $gid)echo '<p>'.h($gs[$gid]??$gid).'</p>';form_start('teacher_revoke',['c'=>$cid,'aid'=>$aid]);end_form('Revocar cuenta completa');echo '</div>';}
 foreach($d['invites'] as $k=>$inv){if(($inv['role']??'')!=='tutor'||$inv['expires']<time())continue;echo '<p class="notice">Invitación pendiente: '.h($inv['email']).'</p>';form_start('teacher_cancel',['c'=>$cid,'key'=>$k]);end_form('Cancelar invitación');}echo '</section>';if($ed&&$gs){echo '<section class="card"><h2>Invitar a un tutor docente</h2>';form_start('teacher_invite',['c'=>$cid]);input('name','Nombre y apellidos','','text',true);input('email','Correo profesional','','email',true);foreach($gs as $gid=>$n)echo '<label class="check"><input type="checkbox" name="groups[]" value="'.h($gid).'">'.h($n).'</label>';end_form('Enviar invitación con Resend');echo '</section>';}
 if(isset($_SESSION['teacher_invite'])){echo '<section class="card"><h2>Enlace privado de activación</h2><p>Compártalo exclusivamente con el docente autorizado. Caduca en siete días.</p><textarea readonly>'.h($_SESSION['teacher_invite']).'</textarea></section>';unset($_SESSION['teacher_invite']);}
}
function teacher_selected_groups(array $d,string $cid):array{$raw=$_POST['groups']??[];if(!is_array($raw))fail('Grupos inválidos');$out=[];foreach($raw as $g){if(!is_string($g)||!isset($d['courses'][$cid]['groups'][$g]))fail('Grupo inválido');$out[]=$g;}return array_values(array_unique($out));}
